# NEW THEORY: Horizontal extension goes from the special pixel toward the NEAREST DIFFERENT BEAM

def solve_v4(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    result = [[grid[r][c] for c in range(n_cols)] for r in range(n_rows)]

    # Step 1: Vertical beams DOWN from each non-zero
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                val = grid[r][c]
                for cr in range(r + 1, n_rows):
                    if result[cr][c] == 0:
                        result[cr][c] = val
                    else:
                        break

    # Step 2: For each row with an ORIGINAL special pixel, extend horizontally
    # Extension goes toward the nearest beam of a DIFFERENT color
    for original_r in range(n_rows):
        for original_c in range(n_cols):
            if grid[original_r][original_c] != 0:
                orig_val = grid[original_r][original_c]

                # Get all beams in THIS row (result after vertical fills)
                row_beams = [(c, result[original_r][c]) for c in range(n_cols) if result[original_r][c] != 0]
                row_beams.sort()

                # Extend RIGHT until hitting a DIFFERENT colored beam
                right_beam = None
                for bc, bv in row_beams:
                    if bc > original_c and bv != orig_val:
                        right_beam = bc
                        break

                if right_beam is not None:
                    for cc in range(original_c, right_beam):
                        result[original_r][cc] = orig_val

                # Extend LEFT until hitting a DIFFERENT colored beam  
                left_beam = None
                for i, (bc, bv) in enumerate(row_beams):
                    if bc < original_c and bv != orig_val:
                        left_beam = bc
                        break

                if left_beam is not None:
                    for cc in range(left_beam, original_c):
                        result[original_r][cc] = orig_val

    return result

