# NEW approach: Maybe the horizontal fill goes UNTIL hitting a DIFFERENT colored beam
# OR UNTIL hitting THE SAME column index where another beam exists?

def solve_v7(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    result = [[grid[r][c] for c in range(n_cols)] for r in range(n_rows)]

    # Step 1: Vertical beams DOWN
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                val = grid[r][c]
                for cr in range(r + 1, n_rows):
                    if result[cr][c] == 0:
                        result[cr][c] = val
                    else:
                        break

    # Step 2: Horizontal fills from ORIGINAL pixels in rows with beams passing through
    for orig_r in range(n_rows):
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                orig_val = grid[orig_r][orig_c]

                # Check if ANY beam passes through THIS row (regardless of column)
                has_beam_in_row = False
                for cc in range(n_cols):
                    # Check if there's a beam at any column in this row
                    # A beam exists here if there's a non-zero ABOVE at same column
                    if orig_r > 0:
                        for rr in range(orig_r):
                            if grid[rr][cc] != 0:
                                has_beam_in_row = True
                                break
                    if has_beam_in_row:
                        break

                if has_beam_in_row:
                    # Fill LEFT
                    for cc in range(orig_c - 1, -1, -1):
                        if result[orig_r][cc] != 0:
                            break
                        result[orig_r][cc] = orig_val

                    # Fill RIGHT
                    for cc in range(orig_c + 1, n_cols):
                        if result[orig_r][cc] != 0:
                            break
                        result[orig_r][cc] = orig_val

    return result

