# NEW THEORY: Each ORIGINAL non-zero pixel extends horizontally toward any BEAM in that direction
def solve_v10(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    result = [[grid[r][c] for c in range(n_cols)] for r in range(n_rows)]

    # Step 1: Vertical beams DOWN
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                val = grid[r][c]
                for cr in range(r + 1, n_rows):
                    if result[cr][c] == 0:
                        result[cr][c] = val
                    else:
                        break

    # Step 2: For each original pixel, extend toward nearby beams
    for orig_r in range(n_rows):
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                orig_val = grid[orig_r][orig_c]

                # Look for beams (non-zero cells from different original pixels) in this row
                for cc in range(n_cols):
                    # Check if this cell is a "beam" (not original pixel itself, and not empty)
                    if cc != orig_c and result[orig_r][cc] != 0:
                        beam_val = result[orig_r][cc]

                        if beam_val != orig_val:
                            # Different colored beam - try filling between them
                            start = min(orig_c, cc)
                            end = max(orig_c, cc)

                            # Fill with orig_val from one side to the other
                            for k in range(start, end + 1):
                                if k == orig_c or k == cc:
                                    continue  # Keep originals/beam positions unchanged
                                result[orig_r][k] = orig_val

    return result

