# NEW THEORY: Horizontal fills ONLY happen in rows that contain at least one ORIGINAL non-zero pixel

def solve_v11(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    result = [[grid[r][c] for c in range(n_cols)] for r in range(n_rows)]

    # Step 1: Vertical beams DOWN
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                val = grid[r][c]
                for cr in range(r + 1, n_rows):
                    if result[cr][c] == 0:
                        result[cr][c] = val
                    else:
                        break

    # Track which rows have original non-zero pixels
    rows_with_originals = set()
    for orig_r in range(n_rows):
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                rows_with_originals.add(orig_r)

    # Step 2: Only horizontal fills in rows WITH original pixels
    for orig_r in rows_with_originals:
        # Get all beam positions in this row
        beams = [(cc, result[orig_r][cc]) for cc in range(n_cols) if result[orig_r][cc] != 0]

        if len(beams) >= 2:
            # Multiple beams exist - fill between them appropriately
            # Sort by column
            beams.sort()

            for cc in range(n_cols):
                if cc not in [b[0] for b in beams]:  # Only fill empty cells
                    # Find which beams bracket this cell
                    left_beam_idx = None
                    right_beam_idx = None
                    for i, bc in enumerate([b[0] for b in beams]):
                        if bc < cc:
                            left_beam_idx = i
                        elif bc > cc and right_beam_idx is None:
                            right_beam_idx = i

                    if left_beam_idx is not None and right_beam_idx is not None:
                        # Cell is between two beams
                        # Fill using LEFT beam's color (or RIGHT?)
                        result[orig_r][cc] = beams[left_beam_idx][1]

    return result

