# NEW THEORY: Each ORIGINAL pixel extends horizontally toward ANY nearby BEAM(s)
# Fill stops when hitting another non-zero cell

def solve_v12(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    result = [[grid[r][c] for c in range(n_cols)] for r in range(n_rows)]

    # Step 1: Vertical beams DOWN
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                val = grid[r][c]
                for cr in range(r + 1, n_rows):
                    if result[cr][c] == 0:
                        result[cr][c] = val
                    else:
                        break

    # Track originals for filling
    rows_with_originals = set()
    for orig_r in range(n_rows):
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                rows_with_originals.add(orig_r)

    # Step 2: For each original pixel in a row with multiple beams, extend horizontally
    for orig_r in rows_with_originals:
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                orig_val = grid[orig_r][orig_c]

                # Check if there are other non-zeros (beams or other originals) in this row
                other_nonzeros = [cc for cc in range(n_cols) 
                                  if cc != orig_c and result[orig_r][cc] != 0]

                if len(other_nonzeros) > 0:
                    # Extend LEFT from orig_c
                    for cc in range(orig_c - 1, -1, -1):
                        if result[orig_r][cc] != 0:
                            break
                        result[orig_r][cc] = orig_val

                    # Extend RIGHT from orig_c
                    for cc in range(orig_c + 1, n_cols):
                        if result[orig_r][cc] != 0:
                            break
                        result[orig_r][cc] = orig_val

    return result

