# FIX: Define a "beam" as a non-zero cell where a beam passes through from ABOVE
# NOT just any non-zero cell (which includes originals)

def solve_v13(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    # Mark which cells are "beam crossings" - where a beam from above passes through
    # A beam crossing happens when: grid[r][c] == 0 AND some grid[cr][c] != 0 for cr < r
    is_beam_crossing = [[False] * n_cols for _ in range(n_rows)]
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                # This is an original - start a beam below
                val = grid[r][c]
                for cr in range(r + 1, n_rows):
                    if is_beam_crossing[cr][c]:
                        break
                    is_beam_crossing[cr][c] = True

    # Now build result: fill beam crossings during construction
    result = [[grid[r][c] for c in range(n_cols)] for r in range(n_rows)]

    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                val = grid[r][c]
                for cr in range(r + 1, n_rows):
                    if is_beam_crossing[cr][c]:
                        result[cr][c] = val
                    else:
                        is_beam_crossing[cr][c] = False

    # Track rows with original pixels
    rows_with_originals = set()
    for orig_r in range(n_rows):
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                rows_with_originals.add(orig_r)

    # Step 2: Horizontal fills ONLY in rows WITH originals, extending toward BEAM CROSSEINGS
    for orig_r in rows_with_originals:
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                orig_val = grid[orig_r][orig_c]

                # Find all beam crossings in this row
                beam_crossings = [cc for cc in range(n_cols) if is_beam_crossing[orig_r][cc]]

                if len(beam_crossings) > 0:
                    # Extend horizontally toward beam crossings
                    # Go LEFT until hitting another beam or edge
                    for cc in range(orig_c - 1, -1, -1):
                        if is_beam_crossing[orig_r][cc]:
                            break
                        result[orig_r][cc] = orig_val

                    # Go RIGHT until hitting another beam or edge
                    for cc in range(orig_c + 1, n_cols):
                        if is_beam_crossing[orig_r][cc]:
                            break
                        result[orig_r][cc] = orig_val

    return result

