# v20: Look for beams from ORIGINAL pixels crossing in this row (not from other demo rows)

def solve_v20(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    # Build result with beams
    result = [[grid[r][c] for c in range(n_cols)] for r in range(n_rows)]

    # Mark beam crossings from original pixels
    is_beam_crossing = [[False] * n_cols for _ in range(n_rows)]
    for orig_r in range(n_rows):
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                val = grid[orig_r][orig_c]
                for cr in range(orig_r + 1, n_rows):
                    if is_beam_crossing[cr][orig_c]:
                        break
                    is_beam_crossing[cr][orig_c] = True

    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                val = grid[r][c]
                for cr in range(r + 1, n_rows):
                    if is_beam_crossing[cr][c]:
                        result[cr][c] = val
                    else:
                        is_beam_crossing[cr][c] = False

    rows_with_originals = set()
    for orig_r in range(n_rows):
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                rows_with_originals.add(orig_r)

    for orig_r in rows_with_originals:
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                orig_val = grid[orig_r][orig_c]

                # Find beams crossing this row
                beams_in_row = [(cc, result[orig_r][cc]) for cc in range(n_cols) if is_beam_crossing[orig_r][cc]]

                # For each original pixel, find nearest BEAMS (different colored ones ideally)
                # and fill TOWARD them

                # Look LEFT
                for target_cc in range(n_cols):
                    if target_cc >= orig_c or not is_beam_crossing[orig_r][target_cc]:
                        continue

                    target_val = result[orig_r][target_cc]
                    if target_val == orig_val:
                        continue  # Same color beams don't trigger filling

                    # Fill from (target_cc+1) to orig_c-1
                    for fill_c in range(target_cc + 1, orig_c):
                        if result[orig_r][fill_c] == 0:
                            result[orig_r][fill_c] = orig_val
                        elif result[orig_r][fill_c] != orig_val:
                            break

                # Look RIGHT  
                for target_cc in range(n_cols):
                    if target_cc <= orig_c or not is_beam_crossing[orig_r][target_cc]:
                        continue

                    target_val = result[orig_r][target_cc]
                    if target_val == orig_val:
                        continue

                    for fill_c in range(orig_c + 1, target_cc):
                        if result[orig_r][fill_c] == 0:
                            result[orig_r][fill_c] = orig_val
                        elif result[orig_r][fill_c] != orig_val:
                            break

    return result

