# v21: Horizontal fill rule - for each row with original pixels, 
# find ALL columns where vertical beams CROSS this row,
# then fill EMPTY cells with appropriate values based on original pixels nearby

def solve_v21(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    # Build result with beams
    result = [[grid[r][c] for c in range(n_cols)] for r in range(n_rows)]

    # Mark beam crossings from ALL originals
    is_beam_crossing = [[False] * n_cols for _ in range(n_rows)]
    beam_val = [[None] * n_cols for _ in range(n_rows)]
    for orig_r in range(n_rows):
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                val = grid[orig_r][orig_c]
                for cr in range(orig_r + 1, n_rows):
                    if is_beam_crossing[cr][orig_c]:
                        break
                    is_beam_crossing[cr][orig_c] = True
                    beam_val[cr][orig_c] = val

    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                val = grid[r][c]
                for cr in range(r + 1, n_rows):
                    if is_beam_crossing[cr][c]:
                        result[cr][c] = val
                    else:
                        is_beam_crossing[cr][c] = False
                        beam_val[cr][c] = None

    rows_with_originals = set()
    for orig_r in range(n_rows):
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                rows_with_originals.add(orig_r)

    for orig_r in rows_with_originals:
        # Collect beam info for this row
        beams = [(cc, beam_val[orig_r][cc], is_beam_crossing[orig_r][cc]) 
                 for cc in range(n_cols) if is_beam_crossing[orig_r][cc]]

        # Sort by column
        beams.sort(key=lambda x: x[0])

        # For each original pixel, figure out which beams to use for filling
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                orig_val = grid[orig_r][orig_c]

                # Find nearest beam(s) on left and right that have DIFFERENT value
                left_beams_diff = [(b[0], b[1]) for b in beams if b[0] < orig_c and b[1] != orig_val]
                right_beams_diff = [(b[0], b[1]) for b in beams if b[0] > orig_c and b[1] != orig_val]

                # Fill TOWARD nearest different beam
                if left_beams_diff:
                    closest_left = min(left_beams_diff, key=lambda x: x[0])
                    for fc in range(closest_left[0] + 1, orig_c):
                        if result[orig_r][fc] == 0:
                            result[orig_r][fc] = orig_val

                if right_beams_diff:
                    closest_right = max(right_beams_diff, key=lambda x: x[0])
                    for fc in range(orig_c + 1, closest_right[0]):
                        if result[orig_r][fc] == 0:
                            result[orig_r][fc] = orig_val

    return result

