# v22: Fill EXTENDING FROM beam-crossed columns OUTWARD in direction of nearest ORIGINAL pixel

def solve_v22(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    # Build result with beams  
    result = [[grid[r][c] for c in range(n_cols)] for r in range(n_rows)]

    # Mark beam crossings
    is_beam_crossing = [[False] * n_cols for _ in range(n_rows)]
    for orig_r in range(n_rows):
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                val = grid[orig_r][orig_c]
                for cr in range(orig_r + 1, n_rows):
                    if is_beam_crossing[cr][orig_c]:
                        break
                    is_beam_crossing[cr][orig_c] = True

    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                val = grid[r][c]
                for cr in range(r + 1, n_rows):
                    if is_beam_crossing[cr][c]:
                        result[cr][c] = val
                    else:
                        is_beam_crossing[cr][c] = False

    rows_with_originals = set()
    for orig_r in range(n_rows):
        for orig_c in range(n_cols):
            if grid[orig_r][orig_c] != 0:
                rows_with_originals.add(orig_r)

    for orig_r in rows_with_originals:
        # Collect beam info
        beams_in_row = [(cc, is_beam_crossing[orig_r][cc]) for cc in range(n_cols) if is_beam_crossing[orig_r][cc]]

        # Sort beams by column
        beams_in_row.sort(key=lambda x: x[0])

        # Get original pixel positions in this row
        orig_pixels = [(oc, grid[orig_r][oc]) for oc in range(n_cols) if grid[orig_r][oc] != 0]

        for orig_col, orig_val in orig_pixels:
            # Find closest beam(s) on left and right
            left_beams = [b for b in beams_in_row if b[0] < orig_col]
            right_beams = [b for b in beams_in_row if b[0] > orig_col]

            if left_beams:
                # Closest beam to the left
                closest_left = max(left_beams, key=lambda x: x[0])[0]
                # Fill RIGHT from beam position toward original (only empty cells)
                for fc in range(closest_left + 1, orig_col):
                    if result[orig_r][fc] == 0:
                        result[orig_r][fc] = orig_val

            if right_beams:
                # Closest beam to the right
                closest_right = min(right_beams, key=lambda x: x[0])[0]
                # Fill LEFT from beam position toward original
                for fc in range(orig_col, closest_right):
                    if result[orig_r][fc] == 0:
                        result[orig_r][fc] = orig_val

    return result

