# v26: Key insight - beams DON'T go down past ANY row with ORIGINAL pixels
# They can only extend between rows WITH original pixels

def solve_v26(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    # Find rows with original pixels
    rows_with_originals = set()
    for r in range(n_rows):
        if any(grid[r][c] != 0 for c in range(n_cols)):
            rows_with_originals.add(r)

    sorted_rows = sorted(rows_with_originals)

    print(f"Rows with originals: {sorted_rows}")

    # Build result - only add beams BETWEEN consecutive rows-with-originals
    result = [[grid[r][c] for c in range(n_cols)] for r in range(n_rows)]

    for i in range(len(sorted_rows) - 1):
        top_row = sorted_rows[i]
        bot_row = sorted_rows[i+1]

        # For each column, if both top_row and bot_row have originals, 
        # fill cells between them with that color
        for c in range(n_cols):
            if grid[top_row][c] != 0 and grid[bot_row][c] != 0:
                val = grid[top_row][c]
                for r in range(top_row + 1, bot_row):
                    if result[r][c] == 0:
                        result[r][c] = val
            elif grid[top_row][c] != 0 and result[bot_row][c] == 0:
                # Top row has original, bottom doesn't - fill all the way to bottom of grid
                val = grid[top_row][c]
                for r in range(top_row + 1, n_rows):
                    if result[r][c] == 0:
                        result[r][c] = val

            elif grid[bot_row][c] != 0 and result[bot_row][c] != 0:
                # Bottom row has original that hasn't been overwritten
                # Check if anything above blocks it
                val = grid[bot_row][c]
                blocked = False
                for r in range(bot_row - 1, top_row, -1):
                    if result[r][c] != 0:
                        blocked = True
                        break
                if not blocked:
                    for r in range(top_row + 1, bot_row):
                        if result[r][c] == 0:
                            result[r][c] = val

    # Now handle horizontal filling
    for orig_r in sorted_rows:
        orig_pixels = [(oc, grid[orig_r][oc]) for oc in range(n_cols) if grid[orig_r][oc] != 0]
        crossing_beams = []

        for c in range(n_cols):
            # Find nearest beam source above or below this row
            source_above = None
            for sr in range(orig_r - 1, -1, -1):
                if sr in rows_with_originals and grid[sr][c] != 0:
                    source_above = (sr, grid[sr][c])
                    break

            source_below = None
            for sr in range(orig_r + 1, n_rows):
                if sr in rows_with_originals and grid[sr][c] != 0:
                    source_below = (sr, grid[sr][c])
                    break

            if source_above:
                crossing_beams.append(('above', c, source_above))
            if source_below:
                crossing_beams.append(('below', c, source_below))

        for orig_col, orig_val in orig_pixels:
            same_val_crossings = [b for b in crossing_beams if b[2][1] == orig_val]

            for direction, beam_col, (src_r, src_val) in same_val_crossings:
                if src_val != orig_val:
                    continue

                if direction == 'above' and beam_col < orig_col:
                    for fc in range(beam_col + 1, orig_col):
                        if result[orig_r][fc] == 0:
                            result[orig_r][fc] = orig_val
                elif direction == 'above' and beam_col > orig_col:
                    for fc in range(orig_col, beam_col):
                        if result[orig_r][fc] == 0:
                            result[orig_r][fc] = orig_val
                elif direction == 'below' and beam_col < orig_col:
                    for fc in range(beam_col + 1, orig_col):
                        if result[orig_r][fc] == 0:
                            result[orig_r][fc] = orig_val
                elif direction == 'below' and beam_col > orig_col:
                    for fc in range(orig_col, beam_col):
                        if result[orig_r][fc] == 0:
                            result[orig_r][fc] = orig_val

    return result

