    rows_with_originals = set()
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                rows_with_originals.add(r)

    sorted_rows = sorted(rows_with_originals)

    # Horizontal filling - per-row rule based on ORIGINAL pixels only
    for orig_r in sorted_rows:
        # Collect all beams crossing this row (their source value matters)
        beams_at_row = []
        for c in range(n_cols):
            # Find which original's beam is here
            for src_r in sorted_rows:
                if src_r < orig_r:
                    continue
                elif src_r > orig_r:
                    break
                else:
                    if grid[src_r][c] != 0:
                        beams_at_row.append((src_r, grid[src_r][c]))
                    break

        # Get original pixels in this row
        orig_pixels = [(oc, grid[orig_r][oc]) for oc in range(n_cols) if grid[orig_r][oc] != 0]

        for orig_col, orig_val in orig_pixels:
            # Look for same-value beams crossing at OTHER columns in THIS row
            # Fill BETWEEN original and those beams
            for beam_col, beam_src_r in enumerate([b[0] for b in beams_at_row]):
                beam_val = [b[1] for b in beams_at_row][beam_col]

                if beam_val != orig_val:
                    continue

                # Fill from beam toward original
                if beam_col < orig_col:
                    for fc in range(beam_col + 1, orig_col):
                        if result[orig_r][fc] == 0:
                            result[orig_r][fc] = orig_val
                else:
                    for fc in range(orig_col, beam_col):
                        if result[orig_r][fc] == 0:
