# v49: Add horizontal fill logic

def solve_v49(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    # Mark which rows contain originals
    row_has_original = []
    for r in range(n_rows):
        cnt = sum(1 for c in range(n_cols) if grid[r][c] != 0)
        row_has_original.append(cnt > 0)

    # Start with empty grid
    result = [[0] * n_cols for _ in range(n_rows)]

    # Step 1: Place ORIGINAL pixels
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                result[r][c] = grid[r][c]

    # Step 2: Vertical beam propagation from EACH ORIGINAL
    flat_orig = []
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                flat_orig.append((r, c))

    for cr, cc in flat_orig:
        val = grid[cr][cc]
        for r2 in range(cr + 1, n_rows):
            if row_has_original[r2]:
                break
            if result[r2][cc] == 0:
                result[r2][cc] = val

    print("After vertical beams:")
    for i in range(min(8, n_rows)):
        print(f"R{i}: {result[i]}")

    # Step 3: Horizontal fill for rows with exactly ONE original
    orig_positions = []
    for r in range(n_rows):
        cnt = sum(1 for c in range(n_cols) if grid[r][c] != 0)
        if cnt == 1:
            for c in range(n_cols):
                if grid[r][c] != 0:
                    orig_positions.append((r, c, grid[r][c]))
                    break

    for r, oc, ov in orig_positions:
        # Find matching beams (same color as original)
        left_beam = None
        right_beam = None

        for fc in range(oc - 1, -1, -1):
            if result[r][fc] == ov:
                left_beam = fc
                break

        for fc in range(oc + 1, n_cols):
            if result[r][fc] == ov:
                right_beam = fc
                break

        print(f"\nR{r}: orig({oc},{ov}), left_b={left_beam}, right_b={right_beam}")

        # Fill only EMPTY cells (== 0), never overwrite beams
        if left_beam is not None:
            for fc in range(left_beam + 1, oc):
                if result[r][fc] == 0:
                    result[r][fc] = ov

        if right_beam is not None:
            for fc in range(oc, right_beam):
                if result[r][fc] == 0:
                    result[r][fc] = ov

    print("\nAfter horizontal fills:")
    for i in range(n_rows):
        print(f"R{i}: {result[i]}")

    return result

