# v52: Add horizontal fill

def solve_v52(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    # Mark which rows contain originals
    row_has_original = []
    for r in range(n_rows):
        cnt = sum(1 for c in range(n_cols) if grid[r][c] != 0)
        row_has_original.append(cnt > 0)

    print("Rows with originals:", row_has_original)

    # Start with empty grid
    result = [[0] * n_cols for _ in range(n_rows)]

    # Step 1: Place ORIGINAL pixels
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                result[r][c] = grid[r][c]

    # Step 2: Vertical beam propagation - enters rows WITH originals
    flat_orig = []
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                flat_orig.append((r, c))

    for cr, cc in flat_orig:
        val = grid[cr][cc]
        for r2 in range(cr + 1, n_rows):
            # Don't break early - allow beams to enter rows with originals
            if result[r2][cc] == 0:
                result[r2][cc] = val

    print("\nAfter vertical beams:")
    for i in range(min(9, n_rows)):
        print(f"R{i}: {result[i]}")

    # Step 3: Horizontal fill for rows with exactly ONE original
    for r in range(n_rows):
        orig_positions = []
        cnt = sum(1 for c in range(n_cols) if grid[r][c] != 0)
        if cnt == 1:
            for c in range(n_cols):
                if grid[r][c] != 0:
                    orig_positions.append((c, grid[r][c]))

        for oc, ov in orig_positions:
            # Find matching colored beams in THIS ROW
            left_beam_pos = None
            right_beam_pos = None

            # Scan left from original
            for fc in range(oc - 1, -1, -1):
                if result[r][fc] == ov:
                    left_beam_pos = fc
                    break

            # Scan right from original
            for fc in range(oc + 1, n_cols):
                if result[r][fc] == ov:
                    right_beam_pos = fc
                    break

            print(f"\nR{r}: orig({ov})@{oc}, L={left_beam_pos}, R={right_beam_pos}")

            # Fill ONLY EMPTY cells
            if left_beam_pos is not None:
                for fc in range(left_beam_pos + 1, oc):
                    if result[r][fc] == 0:
                        result[r][fc] = ov

            if right_beam_pos is not None:
                for fc in range(oc, right_beam_pos):
                    if result[r][fc] == 0:
                        result[r][fc] = ov

    print("\nAfter horizontal fills:")
    for i in range(n_rows):
        print(f"R{i}: {result[i]}")

    return result

